exercises.referenceSolution:
abstract class Shape {
    abstract double area();
    String describe(String name) { return name + ":" + String.format(java.util.Locale.US, "%.1f", area()); }
}
class Circle extends Shape {
    private final double r;
    Circle(double r) { this.r = r; }
    double area() { return Math.PI * r * r; }
}
class Square extends Shape {
    private final double s;
    Square(double s) { this.s = s; }
    double area() { return s * s; }
}
public class Solution {
    public static String describe(String kind, double a) {
        if (kind.equals("circle")) return new Circle(a).describe("circle");
        if (kind.equals("square")) return new Square(a).describe("square");
        return "unknown";
    }
}
